import{_ as t,o as l,c as i,ah as r}from"./chunks/framework.DjU4PSOm.js";const q=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"오늘 강의 개요","slug":"오늘-강의-개요","link":"#오늘-강의-개요","children":[]},{"level":2,"title":"아리스토텔레스와 『니코마코스 윤리학』","slug":"아리스토텔레스와-『니코마코스-윤리학』","link":"#아리스토텔레스와-『니코마코스-윤리학』","children":[]},{"level":2,"title":"목적론적 구조: 텔로스와 목적의 위계","slug":"목적론적-구조-텔로스와-목적의-위계","link":"#목적론적-구조-텔로스와-목적의-위계","children":[{"level":3,"title":"겉보기 선(apparent good) vs 진짜 선(real good)","slug":"겉보기-선-apparent-good-vs-진짜-선-real-good","link":"#겉보기-선-apparent-good-vs-진짜-선-real-good","children":[]},{"level":3,"title":"활동(activity) vs 산물(product)","slug":"활동-activity-vs-산물-product","link":"#활동-activity-vs-산물-product","children":[]},{"level":3,"title":"하위 목적과 종속(subordination) — 현대적 예: 알고리즘","slug":"하위-목적과-종속-subordination-—-현대적-예-알고리즘","link":"#하위-목적과-종속-subordination-—-현대적-예-알고리즘","children":[]},{"level":3,"title":"최고선(the highest good)은 왜 필요한가 — 무한 후퇴 논증","slug":"최고선-the-highest-good-은-왜-필요한가-—-무한-후퇴-논증","link":"#최고선-the-highest-good-은-왜-필요한가-—-무한-후퇴-논증","children":[]},{"level":3,"title":"일원론 vs 다원론 — 아리스토텔레스는 열어둔다","slug":"일원론-vs-다원론-—-아리스토텔레스는-열어둔다","link":"#일원론-vs-다원론-—-아리스토텔레스는-열어둔다","children":[]},{"level":3,"title":"최고선의 후보 검토 — 쾌락, 명예, 부, 성공/인정","slug":"최고선의-후보-검토-—-쾌락-명예-부-성공-인정","link":"#최고선의-후보-검토-—-쾌락-명예-부-성공-인정","children":[]}]},{"level":2,"title":"에우다이모니아(Eudaimonia)란 무엇인가","slug":"에우다이모니아-eudaimonia-란-무엇인가","link":"#에우다이모니아-eudaimonia-란-무엇인가","children":[]},{"level":2,"title":"1권 7장 정독 — 목적론에서 실천적 구조로","slug":"_1권-7장-정독-—-목적론에서-실천적-구조로","link":"#_1권-7장-정독-—-목적론에서-실천적-구조로","children":[{"level":3,"title":"아가톤(agathon)과 실천의 다양성","slug":"아가톤-agathon-과-실천의-다양성","link":"#아가톤-agathon-과-실천의-다양성","children":[]},{"level":3,"title":"프락시스(praxis)와 테크네(technē)","slug":"프락시스-praxis-와-테크네-techne","link":"#프락시스-praxis-와-테크네-techne","children":[]},{"level":3,"title":"내적 선(internal good) vs 외적 선(external good)","slug":"내적-선-internal-good-vs-외적-선-external-good","link":"#내적-선-internal-good-vs-외적-선-external-good","children":[]},{"level":3,"title":"목적(telos)이 행위를 이해 가능하게 만든다","slug":"목적-telos-이-행위를-이해-가능하게-만든다","link":"#목적-telos-이-행위를-이해-가능하게-만든다","children":[]},{"level":3,"title":"각 실천의 목적과 두 단계 평가","slug":"각-실천의-목적과-두-단계-평가","link":"#각-실천의-목적과-두-단계-평가","children":[]},{"level":3,"title":"실천 가능한 선(practicable good) — 조건문으로 남겨진 결론","slug":"실천-가능한-선-practicable-good-—-조건문으로-남겨진-결론","link":"#실천-가능한-선-practicable-good-—-조건문으로-남겨진-결론","children":[]}]},{"level":2,"title":"오늘 강의 핵심 정리","slug":"오늘-강의-핵심-정리","link":"#오늘-강의-핵심-정리","children":[]}],"relativePath":"philosophy/Ethics/02. 아리스토텔레스와 행복(에우다이모니아).md","filePath":"philosophy/Ethics/02. 아리스토텔레스와 행복(에우다이모니아).md"}'),n={name:"philosophy/Ethics/02. 아리스토텔레스와 행복(에우다이모니아).md"};function s(e,o,a,g,u,h){return l(),i("div",null,[...o[0]||(o[0]=[r('<h2 id="오늘-강의-개요" tabindex="-1">오늘 강의 개요 <a class="header-anchor" href="#오늘-강의-개요" aria-label="Permalink to &quot;오늘 강의 개요&quot;">​</a></h2><p>1주차에서 &quot;윤리란 무엇인가&quot;라는 물음으로 시작했다면, 2주차는 아리스토텔레스로 넘어가 더 넓은 질문을 던진다: <strong>인간의 삶 전체를 놓고 보았을 때, 잘 산다는 것은 무엇을 의미하는가?</strong></p><p>아리스토텔레스는 계명 목록이나 보편적 결정 절차, 쾌락 계산으로 시작하지 않는다. 대신 &quot;무엇이 인간에게 최고의 것인가&quot;, &quot;어떤 활동이 번영하는 인간의 삶을 구성하는가&quot;를 묻는 데서 출발한다.</p><p><strong>도입 사례</strong>: 고소득과 사회적 지위를 누리고 대중의 인정을 받아 성공해 보이지만, 자기 일을 좋아하지 않고 의미 있는 우정이 없으며 타인을 단순히 수단으로 대하는 사람 — 이 사람은 정말 행복한 사람인가? 이 망설임이 아리스토텔레스의 핵심 구별을 드러낸다: <strong>삶은 쾌락·성공·부를 담고 있어도 &quot;잘 살아진 삶&quot;이 아닐 수 있다.</strong> 인간의 선(good)은 부나 사회적 인정의 &quot;소유&quot;가 아니라, 인간 능력의 <strong>탁월한 발휘(exercise)</strong>에 있다.</p><p>오늘 강의는 5부로 구성:</p><ol><li>아리스토텔레스와 『니코마코스 윤리학』 소개</li><li>윤리학의 목적론적 구조 (목적의 위계, 도구적/최종적 선, 최고선)</li><li>에우다이모니아(eudaimonia)의 의미</li><li>1권 7장 정독 — 기능 논증</li><li>AI, 구조적 부정의, 소셜미디어, 동물권, 생태적 번영 조건 등 현대적 논의 (다음 시간 예정)</li></ol><h2 id="아리스토텔레스와-『니코마코스-윤리학』" tabindex="-1">아리스토텔레스와 『니코마코스 윤리학』 <a class="header-anchor" href="#아리스토텔레스와-『니코마코스-윤리학』" aria-label="Permalink to &quot;아리스토텔레스와 『니코마코스 윤리학』&quot;">​</a></h2><ul><li>생몰: 기원전 384~322년, 그리스 북부 스타기라 출생. 청년기 아테네로 이주해 <strong>플라톤의 아카데미</strong>에서 수학. 플라톤 사후 여행·연구를 거쳐 아테네로 돌아와 자신의 학교를 설립.</li><li>연구 영역: 논리학, 수학, 생물학, 수사학, 심리학, 시학, 정치학, 윤리학 등 매우 광범위 — 이 폭넓음이 중요한 이유는, 그의 윤리학이 인간 심리·교육·이성적 활동·정치 제도와 분리될 수 없기 때문.</li><li>『니코마코스 윤리학』은 개인이 어떻게 행동해야 하는가를 넘어 <strong>타인과 함께 어떻게 살아야 하는가</strong>를 묻는다 — 아리스토텔레스에게 윤리학과 정치학은 밀접히 연결됨.</li><li>총 10권, 행복·덕·책임·선택·정의·실천적 지혜·의지의 약함·우정·쾌락·사색을 다룸. 제목은 아리스토텔레스의 아버지이자 아들의 이름인 &quot;니코마코스&quot;와 관련되나 정확한 유래는 불확실.</li><li><strong>방법론</strong>: 일상적 관행, 익숙한 구분, 평판 있는 의견에서 출발 — 이것들이 철학적 진리를 결정하진 않지만 탐구가 시작되는 재료를 제공. 예컨대 &quot;행복&quot;이라는 단어를 출발점으로 받아들이되, 그 통념이 비판적 검토를 견딜 수 있는지 묻는다.</li></ul><p><strong>이 책이 여전히 영향력 있는 4가지 이유</strong></p><ol><li><strong>삶 전체의 형태를 평가</strong>함 — 고립된 개별 행위가 아니라, 반복된 행동이 어떻게 습관이 되고, 습관이 성격을 형성하며, 성격이 삶의 방향을 결정하는가를 다룸. (한 번의 정직한 발언은 외견상 정직해 보여도, 그 윤리적 의미는 행위자의 이유·성향·정직을 비용이 들어도 유지하려는 의지에 달림)</li><li><strong>윤리적 지식은 실천적</strong>임 — 용기의 정의를 암기한다고 용감해지지 않는다. 윤리 교육은 지각·판단·욕구·감정·습관·행동을 형성해야 하며, 목표는 덕이 무엇인지 아는 것이 아니라 덕 있게 행동할 능력을 갖추는 것.</li><li><strong>윤리는 정치와 불가분</strong>임 — 인간은 가족·학교·법률 제도·정치 공동체 안에서 성장하며, 제도가 무엇을 가치 있게 여길지·어떤 기회를 받을지·어떤 삶의 형태가 가능한지에 영향을 미침. 즉 아리스토텔레스 윤리학은 개인의 자기계발 프로그램이 아니라 <strong>인간 번영의 사회적 조직</strong>에 관한 것이기도 함.</li><li><strong>규칙 중심 윤리에 대한 대안</strong>을 제시함 — 일반 규칙은 중요하지만 인간의 상황은 매우 다양하고 맥락 의존적이라, 도덕 행위자는 특정 사례에서 무엇이 윤리적으로 관련 있는지 지각해야 함. 이 능력이 나중에 <strong>프로네시스(prōnesis, 실천적 지혜)</strong> 개념으로 발전됨.</li></ol><h2 id="목적론적-구조-텔로스와-목적의-위계" tabindex="-1">목적론적 구조: 텔로스와 목적의 위계 <a class="header-anchor" href="#목적론적-구조-텔로스와-목적의-위계" aria-label="Permalink to &quot;목적론적 구조: 텔로스와 목적의 위계&quot;">​</a></h2><p>아리스토텔레스는 1권을 다음 주장으로 시작한다: <strong>모든 기술, 탐구, 행동, 선택은 어떤 선(good)을 목표로 하는 것처럼 보인다.</strong></p><ul><li><strong>텔로스(telos)</strong>: 끝, 완성, 또는 &quot;그것을 위하여 어떤 일이 행해지는 목적&quot;. 어떤 활동의 텔로스를 묻는 것은 &quot;그 행동이 무엇을 위한 것인가&quot;를 묻는 것.</li><li>예: 학생이 강의를 듣는 이유는 아리스토텔레스와 칸트를 이해하기 위해서일 수도, 과목을 통과하기 위해서일 수도, 학위를 따기 위해서일 수도, 안정적 직업을 준비하기 위해서일 수도, 지적 능력을 계발하기 위해서일 수도 있다 — 이 목적들은 <strong>위계(hierarchy)</strong>를 이룬다. 어떤 목적은 즉각적이고, 어떤 목적은 더 넓어서 좁은 목적들을 설명해준다.</li><li><strong>목적론적 설명은 행위를 이해 가능하게 만든다</strong>: 팔을 드는 동작 하나도 질문, 인사, 투표, 스트레칭, 경고일 수 있다 — 신체적 움직임은 비슷해도 <strong>목적이 다르면 행위 자체가 달라진다.</strong></li><li>아리스토텔레스의 중심 질문: 목적들의 위계가 실천적 삶에 일관성을 부여하는 <strong>궁극적 목적(ultimate end)</strong>에서 마침내 정점에 이르는가?</li></ul><h3 id="겉보기-선-apparent-good-vs-진짜-선-real-good" tabindex="-1">겉보기 선(apparent good) vs 진짜 선(real good) <a class="header-anchor" href="#겉보기-선-apparent-good-vs-진짜-선-real-good" aria-label="Permalink to &quot;겉보기 선(apparent good) vs 진짜 선(real good)&quot;">​</a></h3><p>&quot;모든 행위가 어떤 선을 목표로 한다&quot;는 말은 모든 행위가 실제로 선한 것을 이룬다는 뜻이 아니다. 사람들은 종종 <strong>자신에게 좋아 보이는 것</strong>을 위해 행동한다.</p><ul><li>예: 더 높은 학점이 바람직해 보여서 부정행위를 하는 학생, 관심과 인정이 가치 있어 보여서 거짓 정보를 퍼뜨리는 사람.</li><li>이런 행위는 &quot;겉보기 선(apparent good, 피상적 좋음)&quot;과 관련해서는 이해 가능하지만, 그 목표가 지식·공정성·신뢰·좋은 인격과 충돌할 수 있다.</li><li><strong>이 구별이 중요한 이유</strong>: 욕망(desire)이 잘못될 수 있기 때문 — 우리는 완전히 교육받지 못했거나, 광고에 의해 조작되거나, 내적으로 혼란스러울 수 있다. <ul><li>광고: 스마트폰을 스크롤하며 접하는 수많은 광고 캠페인은 불필요한 소비를 필요한 것처럼 보이게 만들어 충동구매를 유도.</li><li>소셜미디어: 가시성(visibility)을 가치(worth)와 동등한 것처럼 보이게 만듦 — 게시물에 관심·댓글이 많으면 자기만족·흥분을 느끼고, 적으면 타인의 반응에 불안을 느끼는 현상.</li><li>경쟁적 제도: 승리를 정의보다 더 중요한 것처럼 보이게 만듦.</li></ul></li><li>따라서 윤리학은 &quot;우리가 원하는 것을 어떻게 얻는가&quot;뿐 아니라 <strong>&quot;우리의 욕망이 가치 있는 목적을 향해 있고, 인간 삶 안에서 적절히 질서 잡혀 있는가&quot;</strong>를 묻는다.</li></ul><h3 id="활동-activity-vs-산물-product" tabindex="-1">활동(activity) vs 산물(product) <a class="header-anchor" href="#활동-activity-vs-산물-product" aria-label="Permalink to &quot;활동(activity) vs 산물(product)&quot;">​</a></h3><ul><li>건축은 활동이 끝난 후에도 남는 <strong>집</strong>이라는 산물을 만든다 — 이 경우 산물은 활동과 구별된다.</li><li>반면 우정, 이해, 대화, 음악 연주, 덕 있는 행위 같은 선(goods)은 <strong>활동 그 자체 안에서 실현</strong>된다 — 별도의 산물을 만들어내기 때문에만 가치 있는 게 아니다.</li><li>학습은 성적이나 자격증으로 이어질 수 있지만, 학습에 대한 <strong>진정한 이해 자체</strong>는 그것들을 얻기 위한 도구·수단에 불과한 게 아니다.</li><li>이 구별이 나중에 에우다이모니아를 &quot;인간 삶이 완성된 뒤에 획득하는 산물&quot;이 아니라 <strong>&quot;잘 살고 잘 행동하는 지속적 활동 속에서 실현되는 것&quot;</strong>으로 규정하는 데 핵심적인 역할을 함.</li></ul><h3 id="하위-목적과-종속-subordination-—-현대적-예-알고리즘" tabindex="-1">하위 목적과 종속(subordination) — 현대적 예: 알고리즘 <a class="header-anchor" href="#하위-목적과-종속-subordination-—-현대적-예-알고리즘" aria-label="Permalink to &quot;하위 목적과 종속(subordination) — 현대적 예: 알고리즘&quot;">​</a></h3><ul><li>의술은 환자의 건강을 향한 더 넓은 목적에 종속된 하위 실천이 목적을 부여받는다.</li><li><strong>현대적 예</strong>: 엔지니어는 알고리즘을 정확하고 효율적으로 만들려 하지만, 정확성·효율성은 그 자체로 정당화되지 않는다. &quot;이 알고리즘이 무엇을 위해 쓰이는가?&quot; — 질병 진단인가, 지식·자원 분배인가, 광고 클릭 극대화인가, 범죄 행동 예측인가. <strong>기술적 성공이 윤리적 가치를 확립하지 않는다</strong> — 효율적인 시스템도 부당한 목적을 효율적으로 수행할 수 있다.</li></ul><h3 id="최고선-the-highest-good-은-왜-필요한가-—-무한-후퇴-논증" tabindex="-1">최고선(the highest good)은 왜 필요한가 — 무한 후퇴 논증 <a class="header-anchor" href="#최고선-the-highest-good-은-왜-필요한가-—-무한-후퇴-논증" aria-label="Permalink to &quot;최고선(the highest good)은 왜 필요한가 — 무한 후퇴 논증&quot;">​</a></h3><p>모든 목적이 오직 다른 목적을 위해서만 추구된다면, 어떤 욕망도 &quot;그 자체로 선택할 가치가 있는 것&quot;에 결코 도달하지 못한다.</p><ul><li>예시 연쇄: 학위 → 취업을 위해서만 / 취업 → 돈을 벌기 위해서만 / 돈 → 사회적 지위·인정을 위해서만. 이렇게 모든 목적이 또 다른 목적의 수단이라면 끝이 없다.</li><li>이 우려는 단지 논리적인 게 아니라 <strong>실존적</strong>이다 — &quot;이 영어 강의를 왜 듣는가? 학점을 쉽게 얻기 위해서인가, 윤리학 지식을 늘리기 위해서인가?&quot;</li><li><strong>삶을 계속 미루는 문제</strong>: &quot;졸업 후에 인생이 시작될 것이다&quot;, &quot;승진 후에&quot;, &quot;더 큰 부를 얻은 후에&quot;, &quot;충분한 사회적 인정을 받은 후에&quot; — 더 바람직한 미래 조건을 위해 현재를 계속 유예하는 경향. 이런 삶은 매우 활발(active)할 수 있지만 <strong>방향(direction)을 결여</strong>할 수 있다.</li><li>아리스토텔레스는 이 무한한 수단의 연쇄를 근본적 질문으로 끊는다: <strong>&quot;이 모든 것은 다 무엇을 위한 것인가?&quot;</strong> 최종 목적이 없다면 우리의 기획은 생산적이되 무의미할 수 있다.</li><li><strong>최고선은 &quot;가장 큰 항목&quot;이 아니라 질서 원리(ordering principle)</strong>다 — 건강·쾌락·성취·사회적 인정 모두 가치 있을 수 있지만, 어느 것도 무제한으로 삶을 지배해서는 안 된다. 최고선은 하위 선들을 언제 추구/제한/결합/희생해야 하는지 판단하게 해주며, 모든 선을 단일한 동질적 가치로 환원하지 않으면서도 실천적 숙고에 통일성을 부여한다.</li></ul><h3 id="일원론-vs-다원론-—-아리스토텔레스는-열어둔다" tabindex="-1">일원론 vs 다원론 — 아리스토텔레스는 열어둔다 <a class="header-anchor" href="#일원론-vs-다원론-—-아리스토텔레스는-열어둔다" aria-label="Permalink to &quot;일원론 vs 다원론 — 아리스토텔레스는 열어둔다&quot;">​</a></h3><ul><li><strong>합리적 반론</strong>: 인간 삶에는 우정·지식·정의·쾌락·창의성·자유·돌봄 같은 환원 불가능한 다수의 선이 있는데, 왜 &quot;하나의&quot; 최고선이 있어야 하는가?</li><li>아리스토텔레스는 이 다원성을 부정하지 않는다. 그의 주장은 실천적 삶이 <strong>선들이 어떻게 관계 맺고 질서 지어지는지에 대한 설명</strong>을 필요로 한다는 것. <ul><li>예: 커리어와 중병에 걸린 가족을 돌보는 일이 충돌할 때, &quot;둘 다 가치 있다&quot;는 말만으로는 결정을 내릴 수 없다 — 어느 선택이 그 상황에서 잘 사는 삶에 더 부합하는지 물어야 한다.</li></ul></li><li>최고선은 하나의 고립된 대상이 아니라, <strong>복수의 선들이 저마다 적절한 자리를 얻는 포괄적인 번영의 형태</strong>로 이해될 수 있다.</li><li><strong>열린 해석 질문</strong> (강의 후반부에서 다룰 예정): 에우다이모니아는 여러 선의 포괄적 조직인가, 아니면 궁극적으로 사색(contemplation)이라는 하나의 최고 활동을 특권화하는가?</li></ul><h3 id="최고선의-후보-검토-—-쾌락-명예-부-성공-인정" tabindex="-1">최고선의 후보 검토 — 쾌락, 명예, 부, 성공/인정 <a class="header-anchor" href="#최고선의-후보-검토-—-쾌락-명예-부-성공-인정" aria-label="Permalink to &quot;최고선의 후보 검토 — 쾌락, 명예, 부, 성공/인정&quot;">​</a></h3><ul><li><strong>쾌락</strong>: 진정한 가치이지만 그 자체로 인간 번영을 정의할 수 없다. 쾌락은 질적으로 다르며 잔인함·지배·기만을 동반하기도 한다 — 쾌락의 존재가 곧 그 활동이 좋다는 것을 입증하지 않는다.</li><li><strong>명예</strong>: 그것을 부여하는 사람에게 의존하므로 불안정하다. 게다가 사람들은 보통 명예를 <strong>덕의 인정</strong>으로서 추구한다 — 즉 덕이 명예보다 더 근본적이다.</li><li><strong>부</strong>: 명백히 도구적(instrumental)이다. 자본주의·플랫폼 기반 사회에서 가장 바람직해 보이지만, 그것이 가능하게 하는 것을 위해 추구될 뿐 최종 목적일 수 없다.</li><li><strong>전문적 성공/사회적 인정</strong>: 좋은 삶에 속할 수 있으나 충분하지 않다 — 성공은 부당하게 달성될 수 있고, 타인의 승인에 기반한 삶은 그 판단의 변화에 계속 의존한다.</li></ul><h2 id="에우다이모니아-eudaimonia-란-무엇인가" tabindex="-1">에우다이모니아(Eudaimonia)란 무엇인가 <a class="header-anchor" href="#에우다이모니아-eudaimonia-란-무엇인가" aria-label="Permalink to &quot;에우다이모니아(Eudaimonia)란 무엇인가&quot;">​</a></h2><ul><li>대부분의 사람은 최고의 인간적 선을 &quot;에우다이모니아&quot;라 부른다. 번역자에 따라 <strong>&quot;행복(happiness)&quot;</strong>(Bartlett &amp; Collins 등)로도, <strong>&quot;번영(flourishing)&quot;·&quot;복지(well-being)&quot;·&quot;잘 사는 것(living well)&quot;</strong>으로도 옮겨진다.</li><li>이 단계에서 에우다이모니아는 최고선의 <strong>내용</strong>이 아니라 <strong>형식적 역할</strong>을 지칭한다: (1) 그 자체를 위해 선택되어야 하고, (2) 종속적이지 않고 완전(complete)해야 하며, (3) 다른 목적들을 질서 지을 수 있어야 하고, (4) 삶을 선택할 가치 있게 만들기에 충분(sufficient)해야 한다.</li><li>사람마다 행복을 쾌락·덕·지식·사랑하는 관계·공적 성취 중 무엇과 동일시하는지가 다르기 때문에 이 단어 자체로는 합의가 이루어지지 않는다. (자본주의 사회에서는 흔히 행복을 부유한 삶의 조건과 동일시하는 경향이 있다는 지적도 있었음)</li><li>현대 영어의 &quot;happiness&quot;는 흔히 <strong>일시적인 심리 상태</strong>를 가리키지만, 아리스토텔레스의 에우다이모니아는 훨씬 포괄적이다 — 단순한 감정이 아니라 <strong>완전한 삶에 걸쳐 잘 살고 잘 행하는 것</strong>에 관한 것. (부정직하게 행동한 뒤 만족감을 느낄 수도 있고, 정의롭거나 용감한 행동은 고통·위험을 수반할 수도 있다 — 즉각적 감정이 삶의 윤리적 질을 결정하지 않는다.)</li></ul><p><strong>에우다이모니아의 다섯 가지 성격</strong></p><ol><li><strong>활동(activity)이다</strong> — 그리스어 <em>energeia</em>(활동/현실태)로 표현됨. 지식을 가지고 있어도 발휘하지 않을 수 있고, 정의를 이해해도 정의롭게 행동하지 않을 수 있다. 인간 번영은 능력을 <strong>소유</strong>하는 데 있지 않고 <strong>적극적으로 실현</strong>하는 데 있다 — 정의로운 행동을 실제로 실천하는 것이 중요하다.</li><li><strong>완전하다(complete)</strong> — 더 나아간 목적을 위한 수단으로서 추구되지 않는다. 잘 사는 것은 그 자체를 넘어서는 무언가를 만들어내기 때문에 가치 있는 게 아니다.</li><li><strong>자족적(self-sufficient)이다</strong> — 고립을 의미하지 않는다. 아리스토텔레스는 가족, 사회, 친구, 동료 시민을 명시적으로 번영에 충분한 삶 안에 포함시킨다. 핵심은 <strong>공동체 안에서 타인과 함께 잘 사는 법</strong>을 아는 것.</li><li><strong>일부 외부적 선(external goods)을 필요로 한다</strong> — 덕이 있다고 해서 빈곤·질병·억압·고립에 면역이 되는 건 아니다. 외부적 선이 행복을 완전히 구성하는 건 아니지만, 그것이 심각하게 결여되면 탁월함(excellence)의 발휘를 가로막을 수 있다. <ul><li>이 지점에서 <strong>정치적 질문</strong>이 제기됨: 번영이 부분적으로 교육·건강·경제적 조건·우정에 달려 있다면, 번영의 사회적 조건은 어떻게 분배되어야 하는가? → 윤리학과 정치학의 긴밀한 연관.</li></ul></li></ol><h2 id="_1권-7장-정독-—-목적론에서-실천적-구조로" tabindex="-1">1권 7장 정독 — 목적론에서 실천적 구조로 <a class="header-anchor" href="#_1권-7장-정독-—-목적론에서-실천적-구조로" aria-label="Permalink to &quot;1권 7장 정독 — 목적론에서 실천적 구조로&quot;">​</a></h2><p>전 장에서 아리스토텔레스는 <strong>플라톤의 &quot;단일한 보편적 선의 이데아&quot;</strong>(특정한 선한 것들과 별개로 존재하는)를 검토·비판했다. 7장에서는 매우 추상적인 형이상학적 물음(&quot;선의 보편적 형상이 존재하는가?&quot;)에서 <strong>실천적·구체적 윤리 물음</strong>(&quot;실제로 인간의 행동과 선택을 이끌 수 있는 선은 무엇인가?&quot;)으로 전환한다.</p><ul><li>이는 방법론적으로 중요하다: 아리스토텔레스는 윤리학이 분리된 보편 개념 수준에 머무르길 원치 않으며, 인간이 구체적으로 추구·실현할 수 있는 선을 규명하고자 한다. 즉 <strong>선의 형이상학에서 인간 선의 실천적 구조로의 이동</strong>.</li></ul><h3 id="아가톤-agathon-과-실천의-다양성" tabindex="-1">아가톤(agathon)과 실천의 다양성 <a class="header-anchor" href="#아가톤-agathon-과-실천의-다양성" aria-label="Permalink to &quot;아가톤(agathon)과 실천의 다양성&quot;">​</a></h3><ul><li>핵심어는 <strong>아가톤(agathon, 선/좋음)</strong>. 이 단계에서 &quot;좋음&quot;은 도덕적 좋음만을 뜻하지 않고, 더 넓게 <strong>어떤 활동이 성공적 결과·목적으로서 추구하는 바</strong>를 가리킨다.</li><li>좋음은 활동/전문 분야마다 다르게 나타난다 — 의학과 장군술에서 좋음은 서로 다르다. <ul><li>의학의 목적 = <strong>건강</strong>. (많은 부모가 자녀에게 의사가 되길 바라는 사회적 집착의 동기는 안정적 생활 조건·사회적 인정·고소득·경제적 번영에 대한 믿음이지만, 이것들이 의학의 <strong>최종적 선</strong>은 아니다.)</li><li>장군술의 목적 = <strong>승리</strong>.</li></ul></li><li>이는 <strong>도덕적 상대주의가 아니다</strong> — &quot;모든 분야가 자기만의 도덕을 만들며 더 높은 기준은 없다&quot;는 주장이 아니다. 더 제한된 주장: 활동에 내재한 좋음은 <strong>그 활동이 무엇을 위한 것인가</strong>에 달려 있다.</li></ul><h3 id="프락시스-praxis-와-테크네-techne" tabindex="-1">프락시스(praxis)와 테크네(technē) <a class="header-anchor" href="#프락시스-praxis-와-테크네-techne" aria-label="Permalink to &quot;프락시스(praxis)와 테크네(technē)&quot;">​</a></h3><ul><li><strong>프락시스</strong>: 행동/활동.</li><li><strong>테크네</strong>: 공예, 전문성, 실천적 주제 영역 (영어 &quot;technology&quot;의 어원).</li><li>의학, 가정 건축, 군사 지휘는 지식·기술·조직화된 실천 목적을 포함하므로 테크네의 예.</li><li>성공의 기준은 활동마다 다르다 — 성공적인 의학적 치료는 환자를 회복/보호하고, 성공적인 광고 캠페인은 관심/판매를 늘린다.</li><li><strong>중요한 문제</strong>: 실천 내부 기준에서의 성공이 <strong>자동으로 도덕적 선함을 의미하지 않는다.</strong> 군사 지휘관은 부당한 전쟁에서도 승리할 수 있고, 광고 캠페인은 소비자를 성공적으로 조작할 수 있으며, 기업은 착취를 통해 효율적으로 이윤을 늘릴 수 있다. → <strong>실천의 내적 기준에 따른 성공과, 그 실천과 목적에 대한 도덕적 평가는 구분되어야 한다.</strong><ul><li>토론 질문: 어떤 활동이 자체 기준으로는 성공했지만 여전히 도덕적으로 잘못될 수 있는가?</li></ul></li></ul><h3 id="내적-선-internal-good-vs-외적-선-external-good" tabindex="-1">내적 선(internal good) vs 외적 선(external good) <a class="header-anchor" href="#내적-선-internal-good-vs-외적-선-external-good" aria-label="Permalink to &quot;내적 선(internal good) vs 외적 선(external good)&quot;">​</a></h3><ul><li>각 활동/분야에 &quot;속하는&quot; 좋음을 찾음으로써, 그 실천에 <strong>내재한 선</strong>을 그것에 <strong>부수하는 외적 보상</strong>과 구별할 수 있다.</li><li>예: 교육의 내적 선 = 이해, 지적 발전, 비판적 판단, 책임 있는 탐구. 외적 선 = 상, 급여, 순위, 명성. <ul><li>대학이 높은 순위를 얻으면서도 학생을 제대로 교육하지 못할 수 있다 — <strong>외적 척도로는 성공하면서 교육의 내적 선에 관해서는 실패</strong>할 수 있음.</li></ul></li><li>의학의 내적 선은 의사의 높은 소득이 아니다. 소득은 필요할 수 있는 외적 선이지만, 의학은 의학으로서 <strong>환자의 건강</strong>을 향한다. <ul><li>토론 질문: 대학 교육의 내적 선은 무엇인가? (왜 대학에 진학했는가 — 학점/졸업장, 취업을 위한 연구 촉진, 혹은 지식·비판적 사고력 계발을 위해서인가?)</li></ul></li></ul><h3 id="목적-telos-이-행위를-이해-가능하게-만든다" tabindex="-1">목적(telos)이 행위를 이해 가능하게 만든다 <a class="header-anchor" href="#목적-telos-이-행위를-이해-가능하게-만든다" aria-label="Permalink to &quot;목적(telos)이 행위를 이해 가능하게 만든다&quot;">​</a></h3><ul><li>&quot;모든 것이 그것을 위해 행해지는 그것&quot; — 각 활동의 좋음은, 그 활동 내 다른 모든 행위가 <strong>그것을 위해</strong> 수행되는 목적이다.</li><li>의사가 환자를 진찰하고, 검사를 지시하고, 약을 처방하고, 수술을 하는 것은 보통 그 자체를 위해서가 아니라 <strong>환자의 건강을 위해서</strong> 행해진다. 목적은 하위 행위들에 통일성과 이해 가능성을 부여한다.</li><li><strong>목적 없이는 행위 자체를 알 수 없다</strong>: 누군가 칼로 다른 사람의 몸을 가른다면, 맥락 없이는 이것이 수술인지 폭력인지 응급처치인지 운동 훈련인지 알 수 없다 — 물리적 움직임만으로는 행위가 정의되지 않으며, 목적과 실천적 맥락이 행위가 무엇인지 이해하게 해준다.</li><li><strong>주의</strong>: 목적이 모든 수단을 자동으로 정당화한다는 뜻은 아니다. 건강이 의학의 목적이라 해도, 그것이 환자를 속이거나 동의를 무시하거나 특정 환자를 차별하거나 위험을 숨기거나 불필요한 시술을 하는 것을 정당화하지 않는다.</li></ul><h3 id="각-실천의-목적과-두-단계-평가" tabindex="-1">각 실천의 목적과 두 단계 평가 <a class="header-anchor" href="#각-실천의-목적과-두-단계-평가" aria-label="Permalink to &quot;각 실천의 목적과 두 단계 평가&quot;">​</a></h3><ul><li>의학의 목적 = 건강, 군사 지휘의 목적 = 승리, 집짓기의 목적 = 집. 각 경우 목적이 다른 행위들이 왜 수행되는지를 설명한다.</li><li><strong>상업화 문제</strong>: 병원이 큰 이익을 얻지만 환자 건강을 해친다면, 경제적으로는 성공해도 의학적으로는 실패할 수 있다 — 이윤과 환자 건강이 충돌할 때 무엇이 의료 기관을 지배해야 하는가? 아리스토텔레스적 답: <strong>이윤은 의학의 고유한 목적에 종속되어야 한다.</strong></li><li><strong>군사 지휘의 두 단계 평가</strong>: (1) 임상적/기술적 평가 — 지휘관이 승리를 거두었는가? (2) 윤리적·정치적 평가 — 그 전쟁은 정당했는가? 수단은 도덕적으로 용인될 수 있었는가? 승리가 평화와 좋은 정치 공동체에 기여했는가? 이 구분은 <strong>왜 하위 실천이 더 넓은 목적의 질서 안에서 평가되어야 하는지</strong>를 보여준다.</li><li><strong>집짓기</strong>: 목적이 활동과 분리된 산물(집)이라는 점에서 다른 사례들과 다르다 — 건축 활동은 끝나도 집은 남는다. (반면 우정은 별도의 산물이 아니라 <strong>공유된 활동을 통해</strong> 실현된다 — 왜 친구를 원하는가? 순간을 나누기 위해, 혹은 친구로부터 더 효율적으로 정보를 얻기 위해 등.) 이 구분은 나중에 <strong>행복을 외부 산물이 아닌 활동으로 정의</strong>하는 데 중요해진다.</li></ul><h3 id="실천-가능한-선-practicable-good-—-조건문으로-남겨진-결론" tabindex="-1">실천 가능한 선(practicable good) — 조건문으로 남겨진 결론 <a class="header-anchor" href="#실천-가능한-선-practicable-good-—-조건문으로-남겨진-결론" aria-label="Permalink to &quot;실천 가능한 선(practicable good) — 조건문으로 남겨진 결론&quot;">​</a></h3><blockquote><p>&quot;만약 모든 실천적 행위의 하나의 목적이 있다면, 이것이 실천 가능한 선이 될 것이다. 만약 여러 개의 목적이 있다면, 그 여럿이 실천 가능한 선들이 될 것이다.&quot;</p></blockquote><ul><li>이 문장은 이번 강의에서 가장 중요한 문장 중 하나로 강조됨 — 아리스토텔레스는 <strong>아직 하나의 단일 최종 목적이 반드시 있다고 단정하지 않는다.</strong> 그의 진술은 <strong>조건적</strong>이다.</li><li>이는 <strong>윤리적 일원론(monism)</strong>이 아직 증명되지 않았음을 뜻한다. <ul><li><strong>일원론</strong>: 궁극적으로 다른 모든 선을 질서 짓는 하나의 최고선이 존재한다는 입장.</li><li><strong>다원론(pluralism)</strong>: 우정·지식·정의·쾌락·자유처럼 환원 불가능한 여러 최종 선이 있을 수 있다는 입장.</li></ul></li><li>아리스토텔레스는 이 시점에서 두 가능성을 모두 열어둔다. 앞으로 그는 어떤 목적이 단지 도구적인지, 어떤 목적이 그 자체로 선택되는지, 하나의 목적이 다른 것들보다 더 완전한지, 행복이 다른 모든 선을 질서 짓는지를 보여야 한다.</li><li><strong>실천 가능한 선(practicable good)</strong>이라는 개념 자체가 중요한 이유: 이는 편리하거나 현실적인 선을 뜻하는 게 아니라, <strong>인간의 행위를 통해 추구·실현될 수 있는 선</strong>, 즉 실천적 삶에 속하는 선을 뜻한다. 플라톤의 분리된 보편적 선의 이데아는 의사에게 환자를 어떻게 치료할지, 정치인에게 어떻게 통치할지 자동으로 알려주지 않았다는 점에서, 이 전환은 방법론적으로 핵심적이다.</li></ul><h2 id="오늘-강의-핵심-정리" tabindex="-1">오늘 강의 핵심 정리 <a class="header-anchor" href="#오늘-강의-핵심-정리" aria-label="Permalink to &quot;오늘 강의 핵심 정리&quot;">​</a></h2><ul><li>아리스토텔레스는 윤리학을 &quot;이 상황에서 나는 무엇을 해야 하는가&quot;보다 넓은 질문, 즉 <strong>&quot;인간의 삶 전체가 잘 되어간다는 것은 무엇인가&quot;</strong>로 확장한다.</li><li>모든 행위는 어떤 선(목적)을 향하고, 목적들은 <strong>위계</strong>를 이루며, 아리스토텔레스는 이 위계가 어떤 <strong>궁극적 목적</strong>에서 정점에 이르는지를 탐구한다.</li><li>겉보기 선과 진짜 선을 구별해야 하는 이유는 욕망이 왜곡될 수 있기 때문 (광고, 소셜미디어, 경쟁적 제도 등의 예).</li><li>최고선은 최대치의 항목이 아니라 <strong>다른 선들의 자리와 가치를 판단하게 해주는 질서 원리</strong>이며, 무한 후퇴(끝없이 수단으로만 이어지는 목적의 연쇄)를 끊어준다.</li><li><strong>에우다이모니아</strong>는 단순한 감정이 아니라 완전한 삶에 걸친 <strong>활동</strong>이며, 완전하고, 자족적이고(공동체 포함), 어느 정도 외부적 선을 필요로 한다.</li><li>1권 7장은 플라톤적 선의 형이상학에서 <strong>실천 가능한 선</strong>으로의 전환을 보여주며, 아가톤(선)·텔로스(목적)·프락시스/테크네(활동/기술)·내적 선/외적 선의 구별을 통해 각 실천이 어떤 목적을 향하는지 규명한다.</li><li>아직 결론은 조건적: 최종 목적이 하나인지 여럿인지는 <strong>미해결</strong>로 남겨두고, 다음 시간(1권 7장 후반, 기능 논증)으로 이어진다.</li></ul><hr><p><em>출처: KNU Canvas TransLive 실시간 통번역 자막(2026-09-14, 윤리학 001분반 2주차, 윤지영 교수) 및 강의 자료를 바탕으로 직접 재구성한 정리 노트. 원문 자막은 저작권 문제로 리포지토리에 커밋하지 않고 로컬에서만 보관(<a href="./01. 윤리학이란 무엇인가.html">01. 윤리학이란 무엇인가</a> 참고).</em></p>',51)])])}const c=t(n,[["render",s]]);export{q as __pageData,c as default};
